def _spec_type(sp):
    """根据专业方向前缀返回院校类型"""
    _SCI = {"机电","信息技术","电子科技","计算机","工程","建筑","交通","汽车","航空","铁道","装备制造","工业","水利","能源"}
    _BUS = {"财经","商贸","工商管理","经济管理","商务","旅游"}
    _ART = {"艺术","传媒","设计","影视","文化创意"}
    _MED = {"医学","卫生","健康","护理","中医药"}
    _LAW = {"司法","警官","政法"}
    _AGR = {"农业","海事","海洋"}
    if sp in _SCI: return "理工"
    if sp in _BUS: return "财经"
    if sp in _ART: return "艺术"
    if sp in _MED: return "医药"
    if sp in _LAW: return "政法"
    if sp in _AGR: return "农林"
    if sp in ("体育",): return "体育"
    return "综合"


def _brand_type(br):
    """根据品牌词返回院校类型"""
    if br in ("科技","信息","软件","理工","应用","城院"): return "理工"
    if br in ("工商","外国语","国际","商务"): return "财经"
    if br in ("艺术","传媒","设计"): return "艺术"
    return "综合"


